1	import type { Attachment } from "@/types/proto/api/v1/attachment_service_pb";
2	import { getAttachmentType } from "@/utils/attachment";
3	import { formatFileSize, getFileTypeLabel } from "@/utils/format";
4	
5	export interface AttachmentGroups {
6	  visual: Attachment[];
7	  audio: Attachment[];
8	  docs: Attachment[];
9	}
10	
11	export interface AttachmentMetadata {
12	  fileTypeLabel: string;
13	  fileSizeLabel?: string;
14	}
15	
16	export const isImageAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "image/*";
17	export const isVideoAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "video/*";
18	export const isAudioAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "audio/*";
19	
20	export const separateAttachments = (attachments: Attachment[]): AttachmentGroups => {
21	  return attachments.reduce<AttachmentGroups>(
22	    (groups, attachment) => {
23	      if (isImageAttachment(attachment) || isVideoAttachment(attachment)) {
24	        groups.visual.push(attachment);
25	      } else if (isAudioAttachment(attachment)) {
26	        groups.audio.push(attachment);
27	      } else {
28	        groups.docs.push(attachment);
29	      }
30	
31	      return groups;
32	    },
33	    {
34	      visual: [],
35	      audio: [],
36	      docs: [],
37	    },
38	  );
39	};
40	
41	export const getAttachmentMetadata = (attachment: Attachment): AttachmentMetadata => ({
42	  fileTypeLabel: getFileTypeLabel(attachment.type),
43	  fileSizeLabel: attachment.size ? formatFileSize(Number(attachment.size)) : undefined,
44	});
