52	export function buildAttachmentVisualItems(attachments: Attachment[]): AttachmentVisualItem[] {
53	  const attachmentsByGroup = new Map<string, Attachment[]>();
54	  for (const attachment of attachments) {
55	    const groupId = getAttachmentMotionGroupId(attachment);
56	    if (!groupId) {
57	      continue;
58	    }
59	    const group = attachmentsByGroup.get(groupId) ?? [];
60	    group.push(attachment);
