107	  );
108	  const visualNames = new Set(visualAttachments.map((attachment) => attachment.name));
109	  const visualCount = buildAttachmentVisualItems(visualAttachments).length;
110	  const nonVisualCount = attachments.filter((attachment) => !visualNames.has(attachment.name)).length;
