42	    return markdown;
43	  }
44	
45	  const line = lines[lineNumber];
46	
47	  // Match task list patterns: - [ ], - [x], - [X], etc.
48	  const taskPattern = /^(\s*[-*+]\s+)\[([ xX])\](\s+.*)$/;
49	  const match = line.match(taskPattern);
