71	export const remarkMention = () => {
72	  return (tree: Root) => {
73	    visit(tree, (node, index, parent) => {
74	      if (node.type !== "text" || !parent || index === null) return;
75	
76	      const textNode = node as Text;
77	      const segments = parseMentionsFromText(textNode.value);
78	      if (segments.every((segment) => segment.type === "text")) {
79	        return;
80	      }
81	
82	      const newNodes = segments.map((segment) => {
83	        if (segment.type === "mention") {
84	          return createMentionNode(segment.value);
85	        }
86	        return {
87	          type: "text",
88	          value: segment.value,
89	        } as Text;
90	      });
91	
92	      if (typeof index === "number") {
93	        (parent.children as UnistNode[]).splice(index, 1, ...(newNodes as UnistNode[]));
94	      }
95	    });
96	  };
