8	// CommonMark "ASCII punctuation": the only characters a leading backslash can
9	// escape. A backslash before anything else is a literal backslash.
10	function isAsciiPunctuation(char: string): boolean {
11	  if (char.length !== 1) {
12	    return false;
13	  }
14	  const code = char.charCodeAt(0);
15	  return (
16	    (code >= 0x21 && code <= 0x2f) || // ! " # $ % & ' ( ) * + , - . /
17	    (code >= 0x3a && code <= 0x40) || // : ; < = > ? @
18	    (code >= 0x5b && code <= 0x60) || // [ \ ] ^ _ `
19	    (code >= 0x7b && code <= 0x7e) //    { | } ~
