1	export function formatFileSize(bytes: number): string {
2	  if (bytes === 0) return "0 B";
3	  if (bytes < 0) return "Invalid size";
4	
5	  const units = ["B", "KB", "MB", "GB", "TB"];
6	  const k = 1024;
7	  const i = Math.floor(Math.log(bytes) / Math.log(k));
8	  const size = bytes / Math.pow(k, i);
9	  const formatted = i === 0 ? size.toString() : size.toFixed(1);
10	
11	  return `${formatted} ${units[i]}`;
12	}
