14	export function getFileTypeLabel(mimeType: string): string {
15	  if (!mimeType) return "File";
16	
17	  const normalizedMimeType = mimeType.toLowerCase().split(";")[0].trim();
18	  const [category = "", subtype = ""] = normalizedMimeType.split("/");
19	
20	  const specialCases: Record<string, string> = {
21	    "application/pdf": "PDF",
22	    "application/zip": "ZIP",
23	    "application/x-zip-compressed": "ZIP",
24	    "application/json": "JSON",
25	    "application/xml": "XML",
26	    "text/plain": "TXT",
27	    "text/html": "HTML",
28	    "text/css": "CSS",
29	    "text/javascript": "JS",
30	    "application/javascript": "JS",
31	  };
32	
33	  if (specialCases[normalizedMimeType]) {
34	    return specialCases[normalizedMimeType];
35	  }
36	
37	  if (category === "image") {
38	    const imageTypes: Record<string, string> = {
39	      jpeg: "JPEG",
40	      jpg: "JPEG",
41	      png: "PNG",
42	      gif: "GIF",
43	      webp: "WebP",
44	      svg: "SVG",
45	      "svg+xml": "SVG",
46	      bmp: "BMP",
47	      ico: "ICO",
48	    };
49	    return imageTypes[subtype] || subtype.toUpperCase();
50	  }
51	
52	  if (category === "video") {
53	    const videoTypes: Record<string, string> = {
54	      mp4: "MP4",
55	      webm: "WEBM",
56	      ogg: "OGG",
57	      avi: "AVI",
58	      mov: "MOV",
59	      quicktime: "MOV",
60	    };
61	    return videoTypes[subtype] || subtype.toUpperCase();
62	  }
63	
64	  if (category === "audio") {
65	    const audioTypes: Record<string, string> = {
66	      mp3: "MP3",
67	      mpeg: "MP3",
68	      wav: "WAV",
69	      ogg: "OGG",
70	      webm: "WEBM",
71	    };
72	    return audioTypes[subtype] || subtype.toUpperCase();
73	  }
74	
75	  return subtype ? subtype.toUpperCase() : category.toUpperCase();
76	}
